/**
 * BDB Word-export template bytes — generated by
 * `scripts/build-bdb-template.mjs`.
 *
 * The template is `0900 Examples/Basics + Work_areas/Molio 2_Skabelon BDB.docx`.
 * We base64-bundle it here so the renderer can read it synchronously
 * at export time without an async file fetch. The bytes are
 * decoded once at module load.
 *
 * Regenerate by running
 *   `node packages/app/scripts/build-bdb-template.mjs`
 * from the repo root after Tore updates the template file.
 */

/* eslint-disable */

const BASE64 = "";

/**
 * Decode the base64 template once at module load and cache the
 * resulting bytes. Returns a fresh Uint8Array on each call so
 * downstream code can mutate freely without affecting the cache.
 */
let cached: Uint8Array | null = null;

export function getBdbTemplateBytes(): Uint8Array {
  if (cached == null) {
    // Browser-side: `atob` returns a binary string we need to
    // convert byte-by-byte. Faster than fetch + arrayBuffer.
    const binStr = atob(BASE64);
    const out = new Uint8Array(binStr.length);
    for (let i = 0; i < binStr.length; i++) {
      out[i] = binStr.charCodeAt(i);
    }
    cached = out;
  }
  // Return a copy so callers can splice / repack without polluting
  // the shared cache. Copying 56 KB is negligible.
  return new Uint8Array(cached);
}
